void ApplyAll(float t, int seg, float tl, float u)
{
    dbgT = seg == S_IDLE ? -1f : t; dbgSeg = seg;
    ApplyGroups(t, seg, tl);
    ApplyRoad(t, seg, tl);
    ApplyLift(t, seg);
    ApplyGate(t, seg);
    ApplyFall(t, seg, tl);
    ApplySky(t, seg, tl);
    ApplyDelivered(t, seg);
    ApplyPost(t, seg, tl);
    if (deliveredPoems != null && deliveredPoems.useLocalAppliedExposure) deliveredPoems.localAppliedDeltaEV = dbgDEV;
    if (_deliveredStarted) SpawnTick(t, dbgDEV, seg == S_IDLE);
    ApplyBus(t, seg, tl);
    ApplyAudio(t, seg, tl);
    if (deliveredPoems == null) ApplyPoem(seg == S_IDLE ? -1f : t);
    else {
        if (poemRoot != null) poemRoot.gameObject.SetActive(false);
        if (seg == S_IDLE) deliveredPoems.LanbaiBoard(0f);
        else deliveredPoems.LanbaiBoardHide();
    }
    _lastSeg = seg;
    _lastT = seg == S_IDLE ? -1f : t;
}

