// under the second white before act 12). Poses from BusLayout.json door_panels.
private void WriteDoor(float t, bool force)
{
    if (doorPanels == null || _doorOpenPos == null) return;
    int closed = (t >= tAct11 && t < tAct12) ? 1 : 0;
    if (!force && closed == _doorClosed) return;
    _doorClosed = closed;
    for (int i = 0; i < doorPanels.Length && i < _doorOpenPos.Length; i++)
    {
        Transform d = doorPanels[i];
        if (d == null) continue;
        bool haveClosed = doorClosedPos != null && doorClosedYaw != null && i < doorClosedPos.Length && i < doorClosedYaw.Length;
        if (closed == 1 && haveClosed)
        {
            d.localPosition = doorClosedPos[i];
            d.localRotation = _doorOpenRot[i] * Quaternion.Euler(0f, doorClosedYaw[i], 0f);
        }
        else
        {
            d.localPosition = _doorOpenPos[i];
            d.localRotation = _doorOpenRot[i];
        }
    }

        if (_spawnSince < 0f) return;                   // Director v1.2: LB_Journey's spawn fade has the overlay
        float tb = tU12 - 0.25f;
        float Ls = 0.2f, Lb = 0.00129f;
        // Director v1.2: a late joiner whose spawn fade ended while the overlay was ours comes up from black at
        // <= 0.85 EV/s (the frame's ~7.6 EV in ~9 s); the darker of that and the scheduled black wins
        float te = t - _spawnSince;
        bool catchUp = _spawnSince < 1e5f && te >= tb && te < tU12 + 4.0f;
        float aC = 0f;
        if (catchUp)
        {
            float range = Mathf.Log(Ls / Mathf.Max(Lb, 0.004f), 2f);
            aC = EvOverlayAlpha(_spawnSince * 0.85f / Mathf.Max(range, 1e-3f), Lb, Ls, Ls, Lb);
        }
        if (t < tb)
        {
            if (catchUp && aC > 0f) overlay.SetFlat(blackFillS4c, aC, FlashFor(t));
            return;
        }
        if (t < tU12)
        {
            // EV-linear from the frame (APL ~90 at the flash's end) to #030409; darkening is free (bible §1.8)
            float x = (t - tb) / 0.25f;
            float a = EvOverlayAlpha(x, Ls, Lb, Ls, Lb);
            overlay.SetFlat(blackFillS4c, Mathf.Max(a, aC), FlashFor(t));
        }
        else if (t < tU12 + 4.0f)
        {
            overlay.SetFlat(blackFillS6, 1f, 0f);       // cut 1: LB_Journey.ApplyGrades hard-cuts S4c -> S6 in the same frame
        }
    }
}

